import {DEFAULT} from './data.mjs';
import {calculate,sum} from './model.mjs';
import {CLIENT_DEFAULT,renderClientQuote,renderInternal} from './reports.mjs';
import {validate,migrate} from './plan.mjs';
import {donut,foodGroups} from './charts.mjs';
import {renderEquipment,energySummary,kitControls} from './equipment.mjs';
import {renderTeam} from './team.mjs';
import {BRAND_DEFAULT,cleanBrand,LOGO_MAX_CHARS} from './brand.mjs';
import {emptyLibrary,cleanLibrary,saveQuote,duplicateQuote,deleteQuote,searchQuotes,mergeLibrary,backupFile,agoText,displayName} from './quotes.mjs';
import {buildQuotePdf,pdfFileName} from './pdf.mjs';
import {renderRota,defaultRota,setShift,copyDayTo,copyDayToAll,clearDay,addPerson,removePerson,applyRotaToCosts,dayCount} from './rota.mjs';
const KEY='crew-table-plan-v1',LIB_KEY='crew-table-quotes-v1',BRAND_KEY='crew-table-brand-v1',CUR_KEY='crew-table-current-v1';
let rotaDay=0,planTab='crew',state=structuredClone(DEFAULT),view='dashboard',phase=0,recipe=null,query='',reportKind='client';
state.client={...CLIENT_DEFAULT};state.options={...DEFAULT.options};state.rota=defaultRota(state);
const customGroups=new Set(), expandedPanels=new Map([['report-form',true]]);
try{const saved=localStorage.getItem(KEY);if(saved){const candidate=migrate(JSON.parse(saved));validate(candidate);state=candidate;}}catch(e){document.querySelector('#save-status').textContent='Could not load saved plan';}
let library=emptyLibrary(),brand={...BRAND_DEFAULT},quoteId=null,lastSaved='',confirmKey='',quoteQuery='',storageFailed=false;
try{library=cleanLibrary(JSON.parse(localStorage.getItem(LIB_KEY)||'null'));}catch{}
try{brand=cleanBrand(JSON.parse(localStorage.getItem(BRAND_KEY)||'null'));}catch{}
try{const cur=library.quotes.find(q=>q.id===localStorage.getItem(CUR_KEY));if(cur){quoteId=cur.id;lastSaved=JSON.stringify(normalizePlan(cur.plan));}}catch{}
const $=s=>document.querySelector(s), fmt=n=>!Number.isFinite(n)?"n/a":new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:2}).format(n),whole=n=>new Intl.NumberFormat('en-GB',{maximumFractionDigits:0}).format(n),dec=n=>new Intl.NumberFormat('en-GB',{maximumFractionDigits:3}).format(n);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(path,value,label,step=1,min=0,max=100000)=>`<input type="number" data-path="${path}" value="${value}" aria-label="${esc(label)}" min="${min}" max="${max}" step="${step}">`;
const text=(path,value,label,cls='')=>`<input class="${cls}" data-path="${path}" value="${esc(value)}" aria-label="${esc(label)}" maxlength="100">`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageFailed=false;}catch{storageFailed=true;}updateChrome();}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function getPath(path){return path.split('.').reduce((o,k)=>o[k],state)}
function put(path,value){const parts=path.split('.'),key=parts.pop();parts.reduce((o,k)=>o[k],state)[key]=value;}
function quote(c){return `<div class="quote-sheet"><h2>Event quote</h2><p class="quote-caption">${sum(state.phases.map(p=>p.days))} days · ${whole(c.meals)} meals</p>${c.errors.map(e=>`<p class="warning">${esc(e)}</p>`).join('')}<div class="quote-total-label">Selling price before VAT</div><div class="quote-total">${c.errors.length?'Check menu':fmt(c.price)}</div><div class="quote-row"><span>Per person / day</span><b>${c.pd?fmt(c.price/c.pd):'n/a'}</b></div><hr class="quote-rule"><div class="quote-row"><span>Total cost</span><b>${fmt(c.cost)}</b></div><div class="quote-row"><span>${c.kitFee>0?'Profit (incl. equipment fee)':'Profit at '+state.settings.margin+'% margin'}</span><b>${fmt(c.profit)}</b></div><details class="disclosure quote-details" data-panel="quote-breakdown"><summary>Cost breakdown</summary><div class="quote-row"><span>Food & daily extras</span><b>${fmt(c.food)}</b></div><div class="quote-row"><span>Whole-pack top-up</span><b>${fmt(c.uplift)}</b></div><div class="quote-row"><span>Staffing</span><b>${fmt(c.labour)}</b></div><div class="quote-row"><span>Consumables</span><b>${fmt(c.consumables)}</b></div><div class="quote-row"><span>Gas & electric</span><b>${fmt(c.energyCharge)}</b></div><div class="quote-row"><span>Overheads & daily costs</span><b>${fmt(c.fixed+c.daily)}</b></div><div class="quote-row"><span>Contingency (${state.settings.contingency}%)</span><b>${fmt(c.contingency)}</b></div>${c.kitFee>0?`<div class="quote-row"><span>Equipment fee (charged)</span><b>${fmt(c.kitFee)}</b></div>`:''}<div class="quote-row"><span>Average per meal</span><b>${c.meals?fmt(c.price/c.meals):'n/a'}</b></div></details><button class="primary" data-action="csv-quote">Export quote</button><p class="quote-foot">Booker snapshot · 4 Nov 2026<br>Staffing and yields are estimates.</p><details class="disclosure source-details" data-panel="quote-basis"><summary>Pricing & saving notes</summary><p class="quote-foot">Branch prices may vary. Prices do not update automatically. Costs exclude recoverable VAT; selling prices are before VAT.</p><p class="quote-foot">Saved in this browser. Use Plan files to back up or move devices.</p></details>${c.unallocated>.01?`<p class="warning">${fmt(c.unallocated)} is not allocated to a worker group. A phase has costs but no people.</p>`:''}</div>`;}
function phaseTabs(){return `<div class="phase-tabs">${state.phases.map((p,i)=>`<button data-action="phase" data-id="${i}" class="${phase===i?'active':''}" aria-pressed="${phase===i}"><b>${p.name}</b><small>${p.days} days · ${sum(p.groups.map(g=>g.people))} people</small></button>`).join('')}</div>`;}
function compare(c){const two=calculate(state,'two'),three=calculate(state,'three');return `<details class="compare disclosure" data-panel="comparison"><summary>Compare 2 vs 3 meals a day</summary><p class="note">Same headcounts, days and staffing. Two meals means lunch + dinner. Daily extras stay included where selected.</p><table><thead><tr><th>Package</th><th class="numeric">Meals</th><th class="numeric">Per person / day</th><th class="numeric">Event price</th></tr></thead><tbody>${[['Your mixed plan',c],['Everyone on 2 meals',two],['Everyone on 3 meals',three]].map(([label,x])=>`<tr><td>${label}</td><td class="numeric">${whole(x.meals)}</td><td class="numeric">${x.pd?fmt(x.price/x.pd):'n/a'}</td><td class="numeric"><b>${fmt(x.price)}</b></td></tr>`).join('')}</tbody></table><p class="note">Two versus three meals: ${fmt(three.price-two.price)} difference across the event. Comparison does not change your plan.</p></details>`;}
const OPTIONS=[['drinks','Hot drinks','Instant coffee and tea, with milk and sugar','Hot drinks per person per day',1],['fruit','Fruit','Fresh fruit out every day','Servings per person per day',.5],['cereal','Cereal station','Cereal and milk alongside the breakfast baps','Bowls per breakfast (0.5 = half the crew)',.1],['salads','Big salads','Salad bowls with every lunch and dinner','Salads per lunch or dinner',.5]];
function optionCards(c){return `<section class="dash-options"><div class="section-heading"><div><h3>What does the client want?</h3><p>Tick what is included, then choose the stages and amount. The price shows what each one adds.</p></div></div><div class="opt-grid">${OPTIONS.map(([k,label,help,qtyLabel,step])=>{const on=state.options[k],other=calculate({...state,options:{...state.options,[k]:!on}}),diff=Math.abs(c.price-other.price),price=Number.isFinite(diff)?fmt(diff):'n/a';
const chips=state.phases.map((p,i)=>`<label class="chip"><input type="checkbox" data-path="optionStages.${k}.${i}" ${state.optionStages[k][i]?'checked':''} aria-label="${esc(label)} in ${esc(p.name)}"><span>${esc(p.name)}</span></label>`).join('');
return `<div class="opt rich ${on?'on':''}"><label class="opt-head"><input type="checkbox" data-path="options.${k}" ${on?'checked':''}><span class="opt-text"><b>${label}</b><small>${help}</small></span></label>${on?`<div class="opt-detail"><div class="chips" role="group" aria-label="${esc(label)} stages">${chips}</div><label class="qty"><span>${qtyLabel}</span>${num('settings.'+k,state.settings[k],label+' amount',step,0,1000)}</label></div>`:''}<div class="opt-price">${on?`<b>+${price}</b> in quote`:`would add <b>${price}</b>`}</div></div>`}).join('')}</div></section>`;}
function kitSection(c){return `<section class="dash-options"><div class="section-heading"><div><h3>Kitchen kit</h3><p>You own the kit. Choose how this client is charged for it.</p></div></div>${kitControls(state,c,{esc,fmt,whole,num})}</section>`;}
function chartCard(title,note,body){return `<section class="card chart-card"><h3>${title}</h3><p class="note">${note}</p>${body}</section>`;}
function dashboard(c){const h={esc,fmt},days=sum(state.phases.map(p=>p.days)),kpi=(label,value,sub,cls='')=>`<div class="kpi ${cls}"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`,food=foodGroups(state,c);
return `<div class="dashboard-head"><div><h2>Your event at a glance</h2><p>${days} days · ${whole(c.pd)} person-days · ${whole(c.meals)} meals</p></div><div class="dash-actions"><button data-action="csv-quote">Export CSV</button><button class="primary" data-action="navigate" data-target="reports">Client quote</button></div></div>${c.errors.map(e=>`<p class="warning">${esc(e)}</p>`).join('')}
<div class="kpis">${kpi('Quote before VAT',fmt(c.price),(c.pd?fmt(c.price/c.pd):'n/a')+' per person / day','main')}${kpi('Total event cost',fmt(c.cost),'Food, team and overheads')}${kpi('Your profit',fmt(c.profit),state.settings.margin+'% margin'+(c.kitFee>0?' + equipment fee':'')+' <button class="text-link" data-action="navigate" data-target="costs">Edit</button>')}${kpi('Average per meal',c.meals?fmt(c.price/c.meals):'n/a','Before VAT')}</div>
${optionCards(c)}
${kitSection(c)}
<div class="chart-grid">${chartCard('Where your price goes','Every pound of the quote.',donut([{label:'Food',value:c.purchased},{label:'Catering team',value:c.labour},{label:'Consumables',value:c.consumables},{label:'Gas & electric',value:c.energyCharge},{label:'Overheads & contingency',value:c.fixed+c.daily+c.contingency},{label:'Profit',value:c.profit}],h,{centerTop:fmt(c.price),centerBottom:'quote'}))}${chartCard('Price by stage','Build, live and break.',donut(c.phaseCosts.map(p=>({label:p.name+' ('+p.days+' days)',value:p.price})).concat(c.kitFee>0?[{label:'Equipment fee',value:c.kitFee}]:[]),h,{centerTop:days+' days',centerBottom:'on site'}))}${chartCard('Food by meal','Planned food, before whole-pack top-up.',donut(food,h,{centerTop:fmt(sum(food.map(x=>x.value))),centerBottom:'food'}))}</div>
${energySummary(state,c,{esc,fmt,whole})}
<section class="dashboard-phases"><div class="section-heading"><div><h3>Days & crew</h3><p>Change the days here. Open a stage to set people and meals.</p></div></div><div class="phase-overview">${state.phases.map((p,i)=>{const pc=c.phaseCosts[i],meals=sum(c.groups.filter(g=>g.pi===i).map(g=>g.meals));return `<section class="phase-overview-item"><h4>${esc(p.name)}</h4><label>Days ${num('phases.'+i+'.days',p.days,p.name+' days',1,0,365)}</label><dl><div><dt>People / day</dt><dd>${whole(pc.people)}</dd></div><div><dt>Total meals</dt><dd>${whole(meals)}</dd></div><div><dt>Stage quote</dt><dd>${fmt(pc.price)}</dd></div></dl><button data-action="edit-phase" data-id="${i}">Edit ${esc(p.name.toLowerCase())} crew & meals</button></section>`}).join('')}</div></section>
<section class="dashboard-links"><h3>Plan the food</h3><div class="link-row"><button data-action="navigate" data-target="recipes"><span><b>Menu & recipes</b><small>Baps, mains, burgers, salads and portions</small></span><span aria-hidden="true">→</span></button><button data-action="navigate" data-target="shopping"><span><b>Ingredients & shopping</b><small>Pack prices and quantities to buy</small></span><span aria-hidden="true">→</span></button><button data-action="navigate" data-target="costs"><span><b>Costs & margin</b><small>Wages, margin and daily costs</small></span><span aria-hidden="true">→</span></button></div><p class="note">Booker prices checked 4 Nov 2026. Items marked Estimate in the shopping list still need a real price. Staffing and yields are estimates.</p></section>${compare(c)}${c.unallocated>.01?`<p class="warning">${fmt(c.unallocated)} is not allocated to a group. Check stages with costs but no people.</p>`:''}`;}
function equipment(c){return renderEquipment(state,c,{esc,fmt,whole,num,text});}
const today=()=>new Date().toISOString().slice(0,10);
const cf=(key,label,type='text',extra='')=>`<label class="rf">${label}<input type="${type}" data-path="client.${key}" value="${esc(state.client[key])}" ${extra} maxlength="200"></label>`;
const ck=(key,label)=>`<label class="rf check"><input type="checkbox" data-path="client.${key}" ${state.client[key]?'checked':''}> ${label}</label>`;
function reports(c){const h={esc,fmt,whole,today:today(),brand};const cl=state.client;
 const sheet=c.errors.length?`<p class="warning">${esc(c.errors[0])} Fix the menu before sharing a quote.</p>`:reportKind==='client'?renderClientQuote(state,c,calculate(state,'two'),calculate(state,'three'),h):renderInternal(state,c,h);
 return `<div class="report-controls"><div class="section-heading"><div><h2>Reports</h2><p>Make a branded quote for the client, or an internal costing sheet.</p></div><div class="rep-actions">${reportKind==='client'?'<button class="primary" data-action="pdf-report">Download PDF</button>':''}<button data-action="print-report">Print</button></div></div>
<div class="seg" role="group" aria-label="Report type"><button data-action="report-kind" data-kind="client" aria-pressed="${reportKind==='client'}">Client quote</button><button data-action="report-kind" data-kind="internal" aria-pressed="${reportKind==='internal'}">Internal costing</button></div>
${reportKind==='client'?`${brandPanel()}<details class="disclosure report-form" data-panel="report-form" open><summary>Quote details</summary><div class="rf-grid">${cf('clientName','Client name')}${cf('contact','Client contact (email / phone)')}${cf('reference','Quote reference')}${cf('date','Quote date (blank = today)','date')}${cf('validDays','Valid for (days)','number','min="0" max="3650"')}${cf('vat','VAT % (0 = hide VAT)','number','min="0" max="100" step="0.5"')}</div><div class="rf-checks">${ck('showPerPerson','Show price per person / day')}${ck('showMenu','Show example menu')}${ck('showOptions','Show 2 vs 3 meal options')}${ck('showApproval','Show approval box for sign-off')}</div><label class="rf">Notes for the client<textarea data-path="client.notes" rows="3" maxlength="2000" placeholder="e.g. Arrival times, site access, dietary notes">${esc(state.client.notes)}</textarea></label><label class="rf">Terms<textarea data-path="client.terms" rows="4" maxlength="2000">${esc(state.client.terms)}</textarea></label></details>`:''}</div>${sheet}`;}
function plan(c){const tabs=`<div class="seg" role="group" aria-label="Crew view"><button data-action="plan-tab" data-kind="crew" aria-pressed="${planTab==='crew'}">Crew & meals</button><button data-action="plan-tab" data-kind="team" aria-pressed="${planTab==='team'}">Team earnings</button><button data-action="plan-tab" data-kind="rota" aria-pressed="${planTab==='rota'}">Rota</button></div>`;return `<div class="section-heading"><div><h2>${planTab==='team'?'What the team earns':planTab==='rota'?'Rota':'Days & crew'}</h2></div></div>${tabs}${planTab==='team'?renderTeam(state,c,{esc,fmt,whole}):planTab==='rota'?renderRota(state,c,{phase,day:rotaDay,tabs:phaseTabs()},{esc,fmt,whole}):crewMeals(c)}`;}
function crewMeals(c){const p=state.phases[phase],pc=c.phaseCosts[phase];return `${phaseTabs()}<div class="phase-top"><label>${p.name} duration ${num(`phases.${phase}.days`,p.days,p.name+' days',1,0,365)} days</label><span class="phase-total">${pc.people} people per day</span></div><div class="table-wrap"><table class="crew-table"><thead><tr><th>Worker group</th><th>People</th><th>Meals each day</th><th class="numeric">£ / person / day</th></tr></thead><tbody>${p.groups.map((g,i)=>{const a=c.groups.find(x=>x.pi===phase&&x.gi===i),key=g.meals.map(Number).join(''),custom=customGroups.has(phase+':'+i)||!['111','011','101'].includes(key);return `<tr><td>${text(`phases.${phase}.groups.${i}.name`,g.name,'Worker group name','name')}</td><td>${num(`phases.${phase}.groups.${i}.people`,g.people,g.name+' people',1)}</td><td><select class="package" data-package="${i}" aria-label="${esc(g.name)} meal package"><option value="111" ${!custom&&key==='111'?'selected':''}>3 meals</option><option value="011" ${!custom&&key==='011'?'selected':''}>2: lunch + dinner</option><option value="101" ${!custom&&key==='101'?'selected':''}>2: breakfast + dinner</option><option value="custom" ${custom?'selected':''}>Choose meals…</option></select>${custom?`<div class="meal-toggles">${['Breakfast','Lunch','Dinner'].map((m,j)=>`<label><input type="checkbox" data-path="phases.${phase}.groups.${i}.meals.${j}" ${g.meals[j]?'checked':''} aria-label="${esc(g.name+' '+m)}">${m}</label>`).join('')}</div>`:''}</td><td class="numeric phase-cost-label">${a.pd?fmt(a.price/a.pd):'n/a'}</td></tr>`}).join('')}</tbody></table></div><div class="group-tools"><button class="small" data-action="add-group">+ Add group</button><span class="subtle">Example group split. Edit to match your crew.</span></div><details class="disclosure" data-panel="group-options-${phase}"><summary>Remove a group</summary><div class="group-settings">${p.groups.map((g,i)=>`<div class="group-setting"><b>${esc(g.name)}</b><button class="small" data-action="delete-group" data-id="${i}" aria-label="Remove ${esc(g.name)}">Remove</button></div>`).join('')}</div><p class="note">Fruit, hot drinks, cereal and big salads are ticked on the Dashboard. Group prices include allocated labour and overheads. Include catering crew if they eat here.</p></details><div class="phase-summary"><span>${p.name}: ${whole(sum(c.groups.filter(g=>g.pi===phase).map(g=>g.meals)))} meals</span><strong>${fmt(pc.price)} <small>phase quote</small></strong></div>${compare(c)}`;}
function recipes(c){return `<div class="section-heading"><div><h2>Menu & recipes</h2><p>Baps, mains and extras. Edit portions and how often each appears.</p></div></div><div class="source-note">Recipe quantities are draft portions, not tested production recipes. No nuts are specified. Check supplier allergens and cross-contact separately.</div>${['Breakfast','Main','Extra'].map(type=>`<section class="cost-section"><h3>${type==='Extra'?'Big salads, cereal, fruit & hot drinks':type==='Main'?'Lunch & dinner mains':'Breakfast baps'}</h3><p class="note">${type==='Extra'?'Switch these on or off on the Dashboard. Quantities are set in Costs & margin.':'Weights are relative shares, not dates. Tick the stages each one is served in; the rest rebalance. Set 0 to exclude.'}</p>${state.recipes.map((r,i)=>r.type!==type?'':`<div class="recipe-row"><div><button data-action="recipe" data-id="${i}" aria-expanded="${recipe===i}">${esc(r.name)}</button><small>${esc(r.note)} · ${whole(c.servings[i])} planned portions</small>${r.type!=='Extra'?`<div class="phase-chips" role="group" aria-label="${esc(r.name)} served in">${state.phases.map((p,pi)=>`<label><input type="checkbox" data-path="recipes.${i}.phases.${pi}" ${r.phases[pi]?'checked':''}> ${esc(p.name)}</label>`).join('')}</div>`:''}</div><div>${type!=='Extra'?num(`recipes.${i}.weight`,r.weight,r.name+' menu weight',.5):''}${type!=='Extra'?'<small>mix weight</small>':''}</div><strong>${fmt(c.recipeCosts[i])}<small>food / portion</small></strong></div>${recipe===i?recipeEditor(r,i,c):''}`).join('')}</section>`).join('')}<p class="note">All portion costs include ${state.settings.waste}% food buffer. Recipes share ingredients, for example the same bacon in the baps and the carbonara. The shopping list combines them across every recipe.</p>`;}
function recipeEditor(r,i,c){return `<div class="recipe-editor">${text(`recipes.${i}.name`,r.name,'Recipe name','recipe-title-input')}<p>Raw net quantities per portion. Pack yields allow for peel, trim and drained weight. Food cost includes the buffer once.</p><div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Net amount</th><th>Unit</th><th class="numeric">Cost / portion</th><th></th></tr></thead><tbody>${r.lines.map((l,j)=>{const ing=state.ingredients.find(x=>x.id===l.ingredient);return `<tr><td>${esc(ing.name)}</td><td>${num(`recipes.${i}.lines.${j}.qty`,l.qty,ing.name+' quantity',.001)}</td><td>${ing.unit}</td><td class="numeric">${fmt(l.qty*ing.price/(ing.pack*ing.yield)*(1+state.settings.waste/100))}</td><td><button class="delete" data-action="delete-line" data-id="${j}" aria-label="Remove ${esc(ing.name)}">×</button></td></tr>`}).join('')}</tbody></table></div><div class="recipe-add"><select id="new-line" aria-label="Ingredient to add">${state.ingredients.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><button class="small" data-action="add-line">Add ingredient</button><button class="small" data-action="recipe" data-id="${i}">Close recipe</button></div></div>`;}
const field=(key,label,step,help,max=100000)=>`<div class="field"><label for="setting-${key}">${label}</label>${num('settings.'+key,state.settings[key],label,step,0,max).replace('<input','<input id="setting-'+key+'"')}<small>${help}</small></div>`;
function costs(c){const p=state.phases[phase];return `<h2>Costs & margin</h2><p>Set your profit margin, service allowances and staffing budget.</p><div class="fields">${field('margin','Profit margin %',1,'Profit ÷ selling price. 25% margin is a 33.3% markup.',99)}${field('waste','Food buffer %',1,'Extra food allowance, after trim / drained yields.',99)}${field('contingency','Contingency %',1,'Added to the full event cost before profit.',99)}</div><details class="disclosure" data-panel="extras-costs"><summary>Daily extras & consumables</summary><div class="fields">${field('salads','Big salads per main meal',.5,'Applied to every lunch and dinner cover when big salads are ticked.')}${field('cereal','Cereal bowls per breakfast',.1,'0.5 means half the crew have a bowl alongside their bap.')}${field('fruit','Fruit servings / person-day',.5,'One serving = 150g apple in the sample.')}${field('drinks','Hot drinks per person / day',1,'Cups of tea and coffee, with milk and sugar. Cost per cup is in the Hot drinks recipe.')}${field('disposables','Disposables £ / meal',.01,'Plate, cutlery, napkin. Estimate; edit for reusables.')}${field('cups','Disposable cup £ per drink',.01,'Cup and stirrer for each hot drink.')}${field('daily','Cleaning & other £ / day',1,'Cleaning and other daily costs. Gas & electric comes from the Equipment tab.')}</div></details><section class="cost-section"><h3>Catering team</h3><p class="note">Budget total paid hours, including yourself, preparation and washing up. These illustrative daily hours are not a shift rota.</p>${phaseTabs()}<div class="table-wrap"><table><thead><tr><th>Role</th><th>People</th><th>Hours / day</th><th>£ / hour</th><th class="numeric">Phase cost</th></tr></thead><tbody>${p.staff.map((r,i)=>`<tr><td>${text(`phases.${phase}.staff.${i}.name`,r.name,'Staff role','name')}</td><td>${num(`phases.${phase}.staff.${i}.people`,r.people,r.name+' staff count',1)}</td><td>${num(`phases.${phase}.staff.${i}.hours`,r.hours,r.name+' paid hours',.5,0,24)}</td><td>${num(`phases.${phase}.staff.${i}.rate`,r.rate,r.name+' hourly rate',.5)}</td><td class="numeric">${fmt(r.people*r.hours*r.rate*p.days*(1+state.settings.oncost/100))}</td></tr>`).join('')}</tbody></table></div><div class="fields">${field('oncost','Labour on-cost %',1,'Employer costs / agency uplift. Use 0 if already included in rates.',100)}</div></section><details class="disclosure cost-section" data-panel="overheads"><summary>Whole-event overheads</summary><p class="note">Illustrative allowances. Equipment hire is a whole-event amount; update it for your booking length.</p><div class="table-wrap"><table><thead><tr><th>Cost</th><th>Event amount £</th></tr></thead><tbody>${state.overheads.map((o,i)=>`<tr><td>${text(`overheads.${i}.name`,o.name,'Overhead name','name')}</td><td>${num(`overheads.${i}.cost`,o.cost,o.name+' event cost',1)}</td></tr>`).join('')}</tbody></table></div><button class="small" data-action="add-overhead" style="margin-top:12px">+ Add overhead</button></details><p class="note">Enter costs excluding recoverable VAT; include VAT you cannot recover. Quotes are shown before VAT. Refresh rates before committing a quote.</p>`;}
function shopping(c){const rows=c.shopping.filter(i=>!query||`${i.name} ${i.packLabel} ${i.sku}`.toLowerCase().includes(query.toLowerCase()));return `<div class="section-heading"><div><h2>Shopping list</h2><p>${c.shopping.filter(i=>i.packs>0).length} ingredients to buy · ${fmt(c.purchased)} in whole packs</p></div><button class="small" data-action="csv-shopping">Export CSV</button></div><div class="source-note">Booker public prices checked 4 November 2026, before any branch-specific changes. Yellow inputs are editable. Prices do not update automatically.</div><p class="note">Units are kg / litres / each. Bean yields assume 60% drained weight. Cabbage, lettuce and cucumber pack weights are estimates from piece counts. Weigh and update these for accurate costing.</p><div class="shopping-tools"><input id="search" type="search" value="${esc(query)}" placeholder="Find an ingredient…" aria-label="Search ingredients"><button class="small" data-action="add-ingredient">+ Ingredient</button></div><div class="table-wrap"><table class="shopping"><thead><tr><th>Ingredient / source</th><th>Pack units</th><th>Pack £</th><th>Yield %</th><th class="numeric">Need net</th><th class="numeric">Buy packs</th><th class="numeric">Spend</th></tr></thead><tbody>${rows.map(i=>{const idx=state.ingredients.findIndex(x=>x.id===i.id);return `<tr><td class="ingredient-name">${esc(i.name)}<small>${esc(i.packLabel)}</small><small>${i.url.startsWith('https://www.booker.co.uk/')?`<a href="${esc(i.url)}" target="_blank" rel="noopener">Booker ${esc(i.sku)}</a>`:esc(i.status)}${i.status==='Edited price'?' · Edited price':''}</small></td><td>${num(`ingredients.${idx}.pack`,i.pack,i.name+' pack quantity',.001,.001)}<small>${i.unit}</small></td><td>${num(`ingredients.${idx}.price`,i.price,i.name+' pack price',.01)}</td><td><input type="number" data-yield="${idx}" aria-label="${esc(i.name)} usable yield percent" min=".1" max="100" step=".1" value="${Math.round(i.yield*1000)/10}"></td><td class="numeric">${dec(i.needed)}<br><span class="subtle">${i.unit}</span></td><td class="numeric">${i.packs}<br><span class="subtle">${dec(i.spare)} ${i.unit} spare</span></td><td class="numeric"><b>${fmt(i.spend)}</b></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No matching ingredients.</td></tr>'}</tbody></table></div><p class="note">Whole packs are rounded across the event, not each service. Buy perishables in staged deliveries. Spare quantities are charged to this quote; no leftover-stock credit is assumed.</p>`;}
function toTop(){const sh=$('.shell');if(sh&&sh.scrollTo)sh.scrollTo(0,0);window.scrollTo(0,0);}
function focusKey(el){if(!el||el===document.body||!el.dataset)return null;const d=el.dataset;if(d.path)return `[data-path="${d.path}"]`;if(d.equip)return `[data-equip="${d.equip}"]`;if(d.rota)return `[data-rota="${d.rota}"]`;if(d.brand)return `[data-brand="${d.brand}"]`;if(d.package!==undefined)return `[data-package="${d.package}"]`;if(d.yield!==undefined)return `[data-yield="${d.yield}"]`;return el.id?'#'+el.id:null;}
function renderKeepFocus(){const a=document.activeElement,key=focusKey(a);let s0=null,s1=null;try{s0=a.selectionStart;s1=a.selectionEnd;}catch{}render();if(!key)return;const n=document.querySelector(key);if(n&&n!==document.activeElement){n.focus({preventScroll:true});try{if(s0!=null)n.setSelectionRange(s0,s1);else if(n.select)n.select();}catch{if(n.select)n.select();}}}
let soonTimer=0;function renderSoon(){clearTimeout(soonTimer);soonTimer=setTimeout(renderKeepFocus,0);}
function render(){document.querySelectorAll('details[data-panel]').forEach(d=>expandedPanels.set(d.dataset.panel,d.open));const c=calculate(state);$('#event-name').value=state.name;$('#nav').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});$('#content').innerHTML=({dashboard,plan,recipes,costs,shopping,equipment,reports,quotes:quotesView}[view])(c);$('#quote').innerHTML=quote(c);document.querySelector('.workspace').classList.toggle('dashboard-mode',view==='dashboard'||view==='reports'||view==='quotes');$('#quote').hidden=view==='dashboard'||view==='reports'||view==='quotes';$('#print').hidden=view==='dashboard'||view==='reports'||view==='quotes';document.querySelectorAll('details[data-panel]').forEach(d=>d.open=expandedPanels.get(d.dataset.panel)||false);updateChrome();}
document.addEventListener('change',e=>{const el=e.target;try{if(el.dataset.path){if(el.type==='number'&&!el.checkValidity()){el.reportValidity();return;}const old=getPath(el.dataset.path),v=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(el.type==='number'&&el.value===''){toast('Enter a number; use 0 to exclude an item.');el.value=old;return;}put(el.dataset.path,v);try{validate(state)}catch(err){put(el.dataset.path,old);throw err}if(el.dataset.path.startsWith('ingredients.')&&el.dataset.path.endsWith('.price'))state.ingredients[Number(el.dataset.path.split('.')[1])].status='Edited price';save();renderSoon();}
else if(el.dataset.brand!==undefined){brand=cleanBrand({...brand,[el.dataset.brand]:el.value});saveBrand();renderSoon();}
else if(el.id==='logo-file'){const f=el.files&&el.files[0];el.value='';if(f)useLogo(f);}
else if(el.dataset.rota!==undefined){const[pi,di,pid,si]=el.dataset.rota.split(':');setShift(state,+pi,+di,pid,+si,Number(el.value));save();renderSoon();}
else if(el.dataset.equip!==undefined){const[ri,key]=el.dataset.equip.split(':'),list=state.recipes[+ri].equipment;state.recipes[+ri].equipment=el.checked?[...new Set([...list,key])]:list.filter(k=>k!==key);save();renderSoon();}
else if(el.dataset.package!==undefined){const k=phase+':'+el.dataset.package;if(el.value!=='custom'){customGroups.delete(k);state.phases[phase].groups[Number(el.dataset.package)].meals=el.value.split('').map(x=>x==='1');save();}else customGroups.add(k);renderSoon();}
else if(el.dataset.yield!==undefined){if(!el.checkValidity()||el.value===''){el.reportValidity();return;}state.ingredients[+el.dataset.yield].yield=+el.value/100;save();renderSoon();}
}catch(err){toast(err.message);}});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();view='dashboard';render();toTop();});
$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b){view=b.dataset.view;render();toTop();}});
$('#event-name').addEventListener('change',e=>{state.name=e.target.value.trim()||'Festival crew catering';save();});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;$('#content').innerHTML=shopping(calculate(state));$('#search').focus();$('#search').setSelectionRange?.(pos,pos);}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=Number(b.dataset.id),act=b.dataset.action,qid=b.dataset.qid;if(!act.startsWith('q-'))confirmKey='';switch(act){case'pdf-report':exportPdf(state);return;case'save-open':onSaveQuote();return;case'q-open':openQuote(qid);break;case'q-pdf':{const q=library.quotes.find(x=>x.id===qid);if(q)exportPdf(q.plan);return;}case'q-dup':duplicateQ(qid);break;case'q-del':deleteQ(qid);break;case'q-new':newQuote();break;case'logo-clear':brand=cleanBrand({...brand,logo:'',logoRatio:0});saveBrand();break;case'navigate':view=b.dataset.target;break;case'edit-phase':phase=id;view='plan';planTab='crew';break;case'plan-tab':planTab=b.dataset.kind;break;case'rota-day':rotaDay=id;break;case'rota-copy-all':copyDayToAll(state,phase,rotaDay);toast('Day '+(rotaDay+1)+' copied to every day of '+state.phases[phase].name);break;case'rota-copy-next':copyDayTo(state,phase,rotaDay,rotaDay+1);rotaDay=Math.min(rotaDay+1,Math.max(0,dayCount(state.phases[phase])-1));break;case'rota-clear':clearDay(state,phase,rotaDay);break;case'rota-add':addPerson(state);break;case'rota-remove':removePerson(state,id);break;case'rota-apply':toast(applyRotaToCosts(state).message);break;case'phase':phase=id;rotaDay=0;break;case'add-group':state.phases[phase].groups.push({name:'New worker group',people:0,meals:[false,true,true],extras:true});break;case'delete-group':state.phases[phase].groups.splice(id,1);customGroups.clear();break;case'recipe':recipe=recipe===id?null:id;break;case'add-line':{const ingredient=Number($('#new-line').value);state.recipes[recipe].lines.push({ingredient,qty:0});break;}case'delete-line':state.recipes[recipe].lines.splice(id,1);break;case'add-overhead':state.overheads.push({name:'Additional overhead',cost:0});break;case'add-ingredient':{const name=prompt('Ingredient name');if(!name)return;const unit=prompt('Unit: kg, litre or each','kg');if(!['kg','litre','each'].includes(unit)){toast('Use kg, litre or each.');return;}state.ingredients.push({id:Math.max(...state.ingredients.map(i=>i.id))+1,name,unit,pack:1,price:0,yield:1,sku:'',packLabel:'Custom ingredient: enter pack size and price',url:'',checked:'',status:'Your price'});break;}case'csv-quote':exportQuote();return;case'print-report':window.print();return;case'report-kind':reportKind=b.dataset.kind;break;case'csv-shopping':exportShopping();return;}save();render();});
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csv(rows){return rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n');}
function exportQuote(){const c=calculate(state);if(c.errors.length){toast(c.errors[0]);return;}const rows=[['Event',state.name],['Basis','Prices before VAT; Booker snapshot 2026-11-04; staffing and yields assumed'],['Person-days',c.pd],['Meals',c.meals],['Food purchased',c.purchased],['Labour',c.labour],['Consumables',c.consumables],['Overheads and daily costs',c.fixed+c.daily],['Contingency',c.contingency],['Total cost',c.cost],['Profit margin %',state.settings.margin],['Selling price before VAT',c.price],['Operating profit',c.profit],[],['Phase','Group','Person-days','Meals','Cost','Selling price','Selling price / person-day'],...c.groups.map(g=>[state.phases[g.pi].name,g.name,g.pd,g.meals,g.cost.toFixed(2),g.price.toFixed(2),g.pd?(g.price/g.pd).toFixed(2):0])];download('crew-catering-quote.csv',csv(rows),'text/csv');toast('Quote exported');}
function exportShopping(){const c=calculate(state);if(c.errors.length){toast(c.errors[0]);return;}download('crew-catering-shopping.csv',csv([['Ingredient','Unit','Pack units','Pack price','Usable yield','Needed net','Packs','Spend','Spare net','Booker SKU','Pack description','Price status','Source URL','Price checked'],...c.shopping.filter(i=>i.packs).map(i=>[i.name,i.unit,i.pack,i.price,i.yield,i.needed,i.packs,i.spend.toFixed(2),i.spare,i.sku,i.packLabel,i.status,i.url,i.checked])]),'text/csv');toast('Shopping list exported');}
$('#backup').onclick=()=>download('crew-table-plan.json',JSON.stringify(state,null,2),'application/json');$('#restore').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Plan is too large. Choose a Crew Table JSON backup.');const candidate=migrate(JSON.parse(await file.text()));validate(candidate);const previous=state;state=candidate;phase=0;recipe=null;quoteId=null;lastSaved='';setCur();try{render();}catch(err){state=previous;render();throw err;}save();toast('Plan opened');}catch(err){toast('Could not open plan: '+err.message)}e.target.value='';};$('#print').onclick=()=>{view='reports';reportKind='client';render();toTop();};let printPanels=[];window.addEventListener('beforeprint',()=>{printPanels=[...document.querySelectorAll('details')].map(d=>[d,d.open]);printPanels.forEach(([d])=>d.open=true);});window.addEventListener('afterprint',()=>printPanels.forEach(([d,open])=>d.open=open));render();
let installEvent=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;$('#install').hidden=false;});
$('#install').onclick=async()=>{if(!installEvent)return;installEvent.prompt();try{await installEvent.userChoice;}catch{}installEvent=null;$('#install').hidden=true;};
window.addEventListener('appinstalled',()=>{$('#install').hidden=true;toast('Installed. Open Crew Table from your apps or home screen.');});
if('serviceWorker' in navigator&&location.protocol.startsWith('http')){const hadWorker=!!navigator.serviceWorker.controller;navigator.serviceWorker.register('sw.js').catch(()=>{});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadWorker)toast('Updated. Refresh to use the newest version.');});}

// ---- Saved quotes, branding and PDF ----
function normalizePlan(p){const x=migrate(structuredClone(p));validate(x);return x;}
function freshState(){const x=structuredClone(DEFAULT);x.client={...CLIENT_DEFAULT};x.options={...DEFAULT.options};x.rota=defaultRota(x);return x;}
function isDirty(){return !!quoteId&&JSON.stringify(state)!==lastSaved;}
function isPristine(){return JSON.stringify(state)===JSON.stringify(freshState());}
function setCur(){try{localStorage.setItem(CUR_KEY,quoteId||'');}catch{}}
function saveBrand(){try{localStorage.setItem(BRAND_KEY,JSON.stringify(brand));}catch{toast('Could not save your branding on this device.');}}
function persistLibrary(){try{localStorage.setItem(LIB_KEY,JSON.stringify(library));return true;}catch{toast('Could not save: browser storage is full. Download a backup and delete old quotes.');return false;}}
function statusText(){if(storageFailed)return 'Could not save here. Download your plan to keep it.';if(quoteId){const q=library.quotes.find(x=>x.id===quoteId);if(q)return isDirty()?'Unsaved changes: '+displayName(q):'Saved: '+displayName(q)+', '+agoText(q.savedAt,Date.now());}return 'Draft, not saved to Quotes yet';}
function updateChrome(){const st=$('#save-status');if(st)st.textContent=statusText();const sb=$('#save-quote');if(sb)sb.classList.toggle('dirty',quoteId?isDirty():!isPristine());const oq=$('#open-quotes');if(oq)oq.textContent=library.quotes.length?'Quotes ('+library.quotes.length+')':'Quotes';}
function doSaveQuote(){const r=saveQuote(library,state,{id:quoteId,now:Date.now(),rand:Math.random()}),prev=library;library=r.lib;if(!persistLibrary()){library=prev;return false;}quoteId=r.entry.id;lastSaved=JSON.stringify(state);setCur();updateChrome();return true;}
function onSaveQuote(){const name=(state.client.clientName||'').trim();if(quoteId&&name){if(doSaveQuote())toast('Saved '+name);return;}const dlg=$('#save-dialog');$('#sv-client').value=state.client.clientName||'';$('#sv-event').value=state.name;$('#sv-ref').value=state.client.reference||'';if(dlg.showModal)dlg.showModal();else dlg.setAttribute('open','');$('#sv-client').focus();}
$('#save-form').onsubmit=e=>{e.preventDefault();const client=$('#sv-client').value.trim();if(!client){$('#sv-client').focus();return;}state.client.clientName=client.slice(0,200);state.name=($('#sv-event').value.trim()||state.name).slice(0,100);state.client.reference=$('#sv-ref').value.trim().slice(0,200);try{validate(state);}catch(err){toast(err.message);return;}$('#save-dialog').close();const ok=doSaveQuote();save();render();if(ok)toast('Saved '+client);};
$('#sv-cancel').onclick=()=>$('#save-dialog').close();
$('#save-quote').onclick=onSaveQuote;
$('#open-quotes').onclick=()=>{view='quotes';render();toTop();};
function resetViewState(){view='dashboard';phase=0;recipe=null;rotaDay=0;planTab='crew';customGroups.clear();confirmKey='';}
function openQuote(id){const q=library.quotes.find(x=>x.id===id);if(!q)return;if(q.id===quoteId&&!isDirty()){view='dashboard';return;}if(quoteId&&isDirty())doSaveQuote();else if(!quoteId&&!isPristine()&&confirmKey!=='open:'+id){confirmKey='open:'+id;return;}try{const p=normalizePlan(q.plan);state=p;quoteId=q.id;lastSaved=JSON.stringify(p);setCur();resetViewState();toast('Opened '+displayName(q));}catch(err){toast('Could not open this quote: '+err.message);}}
function newQuote(){if(quoteId&&isDirty())doSaveQuote();else if(!quoteId&&!isPristine()&&confirmKey!=='new'){confirmKey='new';return;}state=freshState();quoteId=null;lastSaved='';setCur();resetViewState();toast('New quote started');}
function duplicateQ(id){const r=duplicateQuote(library,id,{now:Date.now(),rand:Math.random()});if(!r.entry)return;const prev=library;library=r.lib;if(!persistLibrary()){library=prev;return;}toast('Duplicated. Open the copy to edit it.');}
function deleteQ(id){const k='del:'+id;if(confirmKey!==k){confirmKey=k;return;}library=deleteQuote(library,id);persistLibrary();if(quoteId===id){quoteId=null;lastSaved='';setCur();}confirmKey='';toast('Quote deleted');}
function quotesView(){const list=searchQuotes(library,quoteQuery),unsaved=!quoteId&&!isPristine();
const cards=list.map(q=>{let price='n/a',sub='';try{const p=normalizePlan(q.plan),c=calculate(p);if(!c.errors.length)price=fmt(c.price);sub=sum(p.phases.map(x=>x.days))+' days · '+whole(c.meals)+' meals';}catch{sub='Could not read this quote';}
const cur=q.id===quoteId,openLabel=confirmKey==='open:'+q.id?'Discard draft and open':cur?'Open':'Open',delLabel=confirmKey==='del:'+q.id?'Tap again to delete':'Delete';
return `<article class="q-card ${cur?'current':''}"><div class="q-main"><b>${esc(displayName(q))}</b><span>${esc(q.event)}</span><small>${cur?(isDirty()?'Open now, unsaved changes':'Open now'):'Saved '+esc(agoText(q.savedAt,Date.now()))}</small></div><div class="q-num"><strong>${price}</strong><small>${esc(sub)} · before VAT</small></div><div class="q-actions"><button class="small primary" data-action="q-open" data-qid="${esc(q.id)}">${openLabel}</button><button class="small q-pdf" data-action="q-pdf" data-qid="${esc(q.id)}">PDF</button><button class="small" data-action="q-dup" data-qid="${esc(q.id)}">Duplicate</button><button class="small ${confirmKey==='del:'+q.id?'danger':''}" data-action="q-del" data-qid="${esc(q.id)}">${delLabel}</button></div></article>`;}).join('');
return `<div class="section-heading"><div><h2>Saved quotes</h2><p>Open a quote to keep working on it, or make a PDF for the client. Quotes are kept in this browser on this device. Use Plan files, Download all quotes, to keep a backup.</p></div><button class="primary" data-action="q-new">${confirmKey==='new'?'Discard draft and start new':'+ New quote'}</button></div>
${unsaved?'<p class="source-note">Your current draft is not saved yet. <button class="small primary" data-action="save-open">Save it now</button></p>':''}
${library.quotes.length?`<div class="shopping-tools"><input id="quote-search" type="search" value="${esc(quoteQuery)}" placeholder="Find a client or event..." aria-label="Search quotes"></div>`:''}
<div class="q-list">${cards||(library.quotes.length?'<p class="empty">No quotes match that.</p>':'<div class="empty-state"><b>No saved quotes yet</b><p>Work on a quote, then press Save quote at the top and name the client. It will appear here.</p></div>')}</div>`;}
document.addEventListener('input',e=>{if(e.target.id==='quote-search'){quoteQuery=e.target.value;const pos=e.target.selectionStart;$('#content').innerHTML=quotesView();const n=$('#quote-search');n.focus();try{n.setSelectionRange(pos,pos);}catch{}}});
function brandPanel(){return `<details class="disclosure report-form" data-panel="brand-panel"><summary>Your branding</summary><div class="rf-grid"><label class="rf">Company name<input data-brand="company" value="${esc(brand.company)}" maxlength="80"></label><label class="rf">Tagline<input data-brand="tagline" value="${esc(brand.tagline)}" maxlength="120"></label><label class="rf">Brand colour<input type="color" data-brand="colour" value="${esc(brand.colour)}"></label><label class="rf">Contact line (email, phone, website)<input data-brand="contact" value="${esc(brand.contact)}" maxlength="200"></label><label class="rf">Footer note (company number, hygiene rating)<input data-brand="footer" value="${esc(brand.footer)}" maxlength="200"></label></div><div class="logo-row">${brand.logo?`<img class="logo-prev" src="${esc(brand.logo)}" alt="Your logo"><button class="small" data-action="logo-clear">Remove logo</button>`:''}<label class="file-btn">${brand.logo?'Change logo':'Upload logo'}<input type="file" id="logo-file" accept="image/png,image/jpeg,image/webp,image/svg+xml"></label><small>Saved on this device and used on every quote and PDF.</small></div></details>`;}
async function useLogo(file){try{if(!/^image\//.test(file.type))throw Error('Choose an image file.');if(file.size>6e6)throw Error('That image is too large. Choose one under 6 MB.');const url=URL.createObjectURL(file);try{const img=await new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=()=>rej(Error('Could not read that image.'));i.src=url;});const iw=img.naturalWidth||300,ih=img.naturalHeight||100,sc=Math.min(1,520/iw,260/ih),w=Math.max(1,Math.round(iw*sc)),h=Math.max(1,Math.round(ih*sc)),cv=document.createElement('canvas');cv.width=w;cv.height=h;cv.getContext('2d').drawImage(img,0,0,w,h);const logo=cv.toDataURL('image/png');if(logo.length>LOGO_MAX_CHARS)throw Error('That logo is too detailed. Try a simpler image.');brand=cleanBrand({...brand,logo,logoRatio:w/h});saveBrand();render();toast('Logo added');}finally{URL.revokeObjectURL(url);}}catch(err){toast(err.message);}}
function loadPdfLib(){if(window.jspdf)return Promise.resolve(window.jspdf);return new Promise((res,rej)=>{const sc=document.createElement('script');sc.src='vendor/jspdf.umd.min.js';sc.onload=()=>window.jspdf?res(window.jspdf):rej(Error('The PDF tool did not load.'));sc.onerror=()=>rej(Error('The PDF tool is not available offline yet. Connect once and try again.'));document.head.append(sc);});}
async function exportPdf(plan){try{const p=normalizePlan(plan),c=calculate(p);if(c.errors.length){toast(c.errors[0]);return;}toast('Making the PDF...');const lib=await loadPdfLib(),doc=buildQuotePdf(lib.jsPDF,p,c,calculate(p,'two'),calculate(p,'three'),brand,today());doc.save(pdfFileName(p));toast('PDF downloaded');}catch(err){toast('Could not make the PDF: '+err.message);}}
$('#backup-all').onclick=()=>download('crew-table-quotes.json',JSON.stringify(backupFile(library,brand),null,2),'application/json');
$('#restore-all').onclick=()=>$('#quotes-file').click();
$('#quotes-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>20e6)throw Error('That file is too large.');const data=JSON.parse(await file.text());if(!data||data.type!=='crew-table-quotes')throw Error('This is not a Crew Table quotes backup.');const ok=[];let skipped=0;for(const q of cleanLibrary(data).quotes){try{ok.push({...q,plan:normalizePlan(q.plan)});}catch{skipped++;}}const prev=library,r=mergeLibrary(library,{quotes:ok});library=r.lib;if(!persistLibrary()){library=prev;return;}if(data.brand&&brand.company===BRAND_DEFAULT.company&&!brand.logo){brand=cleanBrand(data.brand);saveBrand();}render();toast('Backup opened: '+r.added+' added, '+r.updated+' updated'+(skipped?', '+skipped+' skipped':''));}catch(err){toast('Could not open backup: '+err.message);}};
updateChrome();
